9: import FilterManagementView from "./FilterManagementView";
10: import UserProfile from "./UserProfile";
11: import LoginPage from "./LoginPage";
12: import { Notification, View } from "../types";
13: import Sidebar from "./Sidebar";
14: import SettingsView from "./ThemeSettingsView";
15: import MachineModal from "./MachineModal";
16: import { MaintenanceView } from "./MaintenanceView";
17: import DashboardView, { AnalyticsView } from "./DashboardView";
18: import MonthlySummaryView from "./MonthlySummaryView";
19: import FilterGroupModal from "./FilterGroupModal";
20: import MaintenanceModal from "./MaintenanceModal";
21: import ConfirmationDialog from "./ConfirmationDialog";
22: import { themes } from "../utils/themes";
23: import AIAssistantModal from "./AIAssistantModal";
24: import ScannerModal from "./ScannerModal";
