34: import OilManagementView from "./OilManagementView";
35: import { LogoIcon } from "../constants";
36: 
37: const AppContent: React.FC = () => {
38:   const { user, loading: authLoading, signOut } = useAuth();
39:   const { state, actions } = useAppLogic();
40: 
41:   const [isNotificationsOpen, setIsNotificationsOpen] = React.useState(false);
42: 
43:   React.useEffect(() => {
44:     const params = new URLSearchParams(window.location.search);
45:     const machineId = params.get("machineId");
46:     const filterGroupId = params.get("filterGroupId");
47: 
48:     if (user) {
49:       if (machineId) {
50:         actions.selectMachine(machineId);
51:         window.history.replaceState(
52:           {},
53:           document.title,
54:           window.location.pathname
55:         );
56:       } else if (filterGroupId) {
57:         actions.navigateToFilterGroup(filterGroupId);
58:         window.history.replaceState(
59:           {},
60:           document.title,
61:           window.location.pathname
62:         );
63:       }
64:     }
65:   }, [user, actions]);
66: 
67:   React.useEffect(() => {
68:     const root = window.document.documentElement;
69:     const customStyleTagId = "custom-theme-styles";
70: 
71:     const classesToRemove = Array.from(root.classList).filter((cls) =>
72:       cls.startsWith("theme-")
73:     );
74:     if (classesToRemove.length > 0) {
75:       root.classList.remove(...classesToRemove);
76:     }
77:     const oldStyleTag = document.getElementById(customStyleTagId);
78:     if (oldStyleTag) {
79:       oldStyleTag.remove();
80:     }
81:     root.classList.remove("dark", "theme-custom");
82: 
83:     if (state.theme.startsWith("custom")) {
84:       const style = document.createElement("style");
85:       style.id = customStyleTagId;
86:       const colors = state.customColors;
87: 
88:       style.innerHTML = `
89:         .theme-custom {
90:           --background: ${hexToHsl(colors.background)};
91:           --foreground: ${hexToHsl(colors.foreground)};
92:           --muted-foreground: ${hexToHsl(colors.foregroundSecondary)};
93:           --card: ${hexToHsl(colors.card)};
94:           --card-foreground: ${hexToHsl(colors.cardForeground)};
95:           --popover: ${hexToHsl(colors.card)};
96:           --popover-foreground: ${hexToHsl(colors.cardForeground)};
97:           --primary: ${hexToHsl(colors.primary)};
98:           --primary-foreground: ${hexToHsl(colors.primaryForeground)};
99:           --secondary: ${hexToHsl(colors.accent)};
100:           --secondary-foreground: ${hexToHsl(colors.cardForeground)};
101:           --muted: ${hexToHsl(colors.accent)};
102:           --accent: ${hexToHsl(colors.accent)};
103:           --accent-foreground: ${hexToHsl(colors.cardForeground)};
104:           --destructive: ${hexToHsl(colors.destructive)};
105:           --destructive-foreground: ${hexToHsl(colors.destructiveForeground)};
106:           --border: ${hexToHsl(colors.border)};
107:           --input: ${hexToHsl(colors.input)};
108:           --ring: ${hexToHsl(colors.ring)};
109:           --warning: 38 92% 50%;
110:           --warning-foreground: 48 96% 6%;
111: 
112:           ${colors.backgroundImage ? `
113:             --background: transparent;
114:             --card: ${hexToHsl(colors.card)} / 0.85;
115:           ` : ''}
116:         }
117:         
118:         ${colors.backgroundImage ? `
119:         body {
120:           background-image: url(${colors.backgroundImage});
121:           background-size: cover;
122:           background-position: center;
123:           background-attachment: fixed;
124:           background-repeat: no-repeat;
125:           background-color: hsl(${hexToHsl(colors.background)});
126:         }
127:         ` : ''}
128:       `;
129:       document.head.appendChild(style);
130:       root.classList.add("theme-custom");
131: 
132:       if (isColorDark(colors.background)) {
133:         root.classList.add("dark");
134:       }
135:     } else {
136:       root.classList.add(`theme-${state.theme}`);
137:       const selectedThemeInfo = themes.find((t) => t.id === state.theme);
138:       if (selectedThemeInfo?.type === "dark") {
139:         root.classList.add("dark");
140:       }
141:     }
142:   }, [state.theme, state.customColors]);
143: 
144:   const handleLogout = async () => {
145:     try {
146:       await signOut();
147:     } catch (error) {
148:       console.error("Logout failed:", error);
149:     }
150:   };
151: 
152:   const renderLoadingScreen = () => (
153:     <div className="min-h-screen w-full flex flex-col items-center justify-center bg-background">
154:       <LogoIcon className="h-12 w-12 text-primary animate-pulse" />
155:       <p className="mt-4 text-muted-foreground">Chargement...</p>
156:     </div>
157:   );
158: 
159:   if (authLoading) {
160:     return renderLoadingScreen();
161:   }
162: 
163:   if (!user) {
164:     return (
165:       <div className="min-h-screen bg-background text-foreground">
166:         <LoginPage />
167:       </div>
168:     );
169:   }
170: 
171:   if (state.isLoading) {
172:     return renderLoadingScreen();
173:   }
174: 
175:   const renderView = () => {
176:     switch (state.currentView) {
177:       case View.DASHBOARD:
178:         return (
179:           <DashboardView
180:             machines={state.machines}
181:             filterGroups={state.filterGroups}
182:             maintenanceRecords={state.maintenanceRecords}
183:             onSelectMachine={actions.selectMachine}
184:             onSetView={actions.setCurrentView}
185:           />
186:         );
187:       case View.MACHINE_LIST:
188:         return (
189:           <MachineListView
190:             machines={state.machines}
191:             onSelectMachine={actions.selectMachine}
192:             onAddMachine={() => actions.openMachineModal(null)}
193:             onEditMachine={(machine) => actions.openMachineModal(machine)}
194:             onDeleteMachine={actions.deleteMachine}
195:             onOpenConfirmationDialog={actions.openConfirmationDialog}
196:             theme={state.theme}
197:             customCardBorders={state.customColors.cardBorders}
198:             onOpenImportModal={actions.openImportModal}
199:           />
200:         );
201:       case View.MACHINE_DETAIL:
202:         if (!state.selectedMachine) return null;
203:         return (
204:           <MachineDetailView
205:             machine={state.selectedMachine}
206:             filterTypes={state.filterTypes}
207:             filterGroups={state.filterGroups}
208:             onAssignFilter={actions.assignFilterToMachine}
209:             onAddFilterType={actions.addFilterTypeToMachine}
210:             onRemoveFilterType={actions.removeFilterTypeFromMachine}
211:             onBack={() => actions.setCurrentView(View.MACHINE_LIST)}
212:             onOpenConfirmationDialog={actions.openConfirmationDialog}
213:             maintenanceRecords={state.maintenanceRecords}
214:             onOpenMaintenanceModal={actions.openMaintenanceModal}
215:             onDeleteMaintenance={actions.deleteMaintenanceRecord}
216:           />
217:         );
218:       case View.FILTER_MANAGEMENT:
219:         return (
220:           <FilterManagementView
221:             filterGroups={state.filterGroups}
222:             filterTypes={state.filterTypes}
223:             onDeleteGroup={actions.deleteFilterGroup}
224:             onOpenFilterGroupModal={actions.openFilterGroupModal}
225:             onOpenConfirmationDialog={actions.openConfirmationDialog}
226:             highlightedFilterGroupId={state.highlightedFilterGroupId}
227:             onClearHighlight={actions.clearHighlightedFilterGroup}
228:             onOpenAddStockModal={actions.openAddStockModal}
229:           />
230:         );
231:       case View.MAINTENANCE:
232:         return (
233:           <MaintenanceView
234:             maintenanceRecords={state.maintenanceRecords}
235:             machines={state.machines}
236:             onOpenMaintenanceModal={actions.openMaintenanceModal}
237:             onDeleteMaintenance={actions.deleteMaintenanceRecord}
238:             onOpenConfirmationDialog={actions.openConfirmationDialog}
239:             onOpenMaintenanceImportModal={actions.openMaintenanceImportModal}
240:             addToast={actions.addToast}
241:           />
242:         );
243:       case View.ANALYTICS:
244:         return (
245:           <AnalyticsView
246:             machines={state.machines}
247:             filterGroups={state.filterGroups}
248:             maintenanceRecords={state.maintenanceRecords}
249:             filterTypes={state.filterTypes}
250:           />
251:         );
252:       case View.SETTINGS:
253:         return (
254:           <SettingsView
255:             currentTheme={state.theme}
256:             savedThemes={state.savedThemes}
257:             onThemeChange={actions.setTheme}
258:             onOpenCustomizer={actions.openThemeCustomizer}
259:             onDeleteTheme={actions.deleteCustomTheme}
260:             onOpenConfirmationDialog={actions.openConfirmationDialog}
261:           />
262:         );
263:       case View.USER_PROFILE:
264:         return <UserProfile />;
265:       case View.MONTHLY_SUMMARY:
266:         return (
267:           <MonthlySummaryView
268:             machines={state.machines}
269:             maintenanceRecords={state.maintenanceRecords}
270:             addToast={actions.addToast}
271:           />
272:         );
273:       case View.SPARE_PARTS:
274:         return (
275:           <SparePartsView
276:             spareParts={state.spareParts}
277:             installations={state.sparePartInstallations}
278:             machines={state.machines}
279:             onAddSparePart={() => actions.openSparePartModal(null)}
280:             onEditSparePart={actions.openSparePartModal}
281:             onDeleteSparePart={actions.deleteSparePart}
282:             onAddInstallation={actions.openInstallationModal}
283:             onOpenConfirmationDialog={actions.openConfirmationDialog}
284:           />
285:         );
286:       case View.OIL_MANAGEMENT:
287:         return (
288:           <OilManagementView
289:             machines={state.machines}
290:             oilStocks={state.oilStocks}
291:             onUpdateStock={(actions as any).updateOilStocks}
292:             addToast={actions.addToast}
293:           />
294:         );
295:       default:
296:         return (
297:           <DashboardView
298:             machines={state.machines}
299:             filterGroups={state.filterGroups}
300:             maintenanceRecords={state.maintenanceRecords}
301:             onSelectMachine={actions.selectMachine}
302:             onSetView={actions.setCurrentView}
303:           />
304:         );
305:     }
306:   };
307: 
308:   const handleNotificationClick = (notification: Notification) => {
309:     actions.handleNotificationClick(notification);
310:     setIsNotificationsOpen(false);
311:   };
312: 
313:   const handleScanSuccess = (filterGroupId: string) => {
314:     actions.navigateToFilterGroup(filterGroupId);
315:     actions.closeScanner();
316:   };
317: 
318:   return (
319:     <div className="min-h-screen bg-background text-foreground">
320:       <Sidebar
321:         currentView={state.currentView}
322:         setCurrentView={actions.setCurrentView}
323:         isMobileOpen={state.isSidebarOpen}
324:         closeSidebar={actions.closeSidebar}
325:       />
326:       <div className="flex flex-col md:pl-64">
327:         <Header
328:           currentView={state.currentView}
329:           selectedMachine={state.selectedMachine}
330:           onMenuClick={actions.toggleSidebar}
331:           notifications={state.notifications}
332:           isNotificationsOpen={isNotificationsOpen}
333:           onToggleNotifications={() => setIsNotificationsOpen((p) => !p)}
334:           onCloseNotifications={() => setIsNotificationsOpen(false)}
335:           onNotificationClick={handleNotificationClick}
336:           onMarkAllNotificationsAsRead={actions.markAllNotificationsAsRead}
337:           onOpenAIAssistant={actions.openAIAssistant}
338:           onOpenScanner={actions.openScanner}
339:           machines={state.machines}
340:           filterGroups={state.filterGroups}
341:           spareParts={state.spareParts}
342:           onSelectMachine={actions.selectMachine}
343:           onNavigateToGroup={actions.navigateToFilterGroup}
344:           onSetView={actions.setCurrentView}
345:           user={user}
346:           userEmail={user?.email || ""}
347:           onLogout={handleLogout}
348:           savedThemes={state.savedThemes}
349:           currentTheme={state.theme}
350:           onThemeChange={actions.setTheme}
351:         />
352:         <main className="relative flex-1 p-4 sm:p-6 lg:p-8">
353:           {renderView()}
354:         </main>
355:       </div>
356: 
357:       <ToastContainer toasts={state.toasts} onDismiss={actions.removeToast} />
358: 
359:       {state.isScannerOpen && (
360:         <ScannerModal
361:           isOpen={state.isScannerOpen}
362:           onClose={actions.closeScanner}
363:           onScan={handleScanSuccess}
364:         />
365:       )}
366:       {state.isAIAssistantOpen && (
367:         <AIAssistantModal
368:           isOpen={state.isAIAssistantOpen}
369:           onClose={actions.closeAIAssistant}
370:           filterGroups={state.filterGroups}
371:           onNavigateToGroup={actions.navigateToFilterGroup}
372:         />
373:       )}
374:       {state.isMachineModalOpen && (
375:         <MachineModal
376:           isOpen={state.isMachineModalOpen}
377:           onClose={actions.closeMachineModal}
378:           onSave={actions.saveMachine}
379:           machine={state.editingMachine}
380:         />
381:       )}
382:       {state.isFilterGroupModalOpen && (
383:         <FilterGroupModal
384:           isOpen={state.isFilterGroupModalOpen}
385:           onClose={actions.closeFilterGroupModal}
386:           onSave={actions.saveFilterGroup}
387:           group={state.editingFilterGroup}
388:           filterTypes={state.filterTypes}
389:           allFilterGroups={state.filterGroups}
390:         />
391:       )}
392:       {state.isMaintenanceModalOpen && (
393:         <MaintenanceModal
394:           isOpen={state.isMaintenanceModalOpen}
395:           onClose={actions.closeMaintenanceModal}
396:           onSave={actions.saveMaintenanceRecord}
397:           machines={state.machines}
398:           filterTypes={state.filterTypes}
399:           filterGroups={state.filterGroups}
400:           oilStocks={state.oilStocks}
401:           record={state.editingMaintenanceRecord}
402:           viewOnly={state.isMaintenanceViewOnly}
403:         />
404:       )}
405:       {state.isAddStockModalOpen && (
406:         <AddStockModal
407:           isOpen={state.isAddStockModalOpen}
408:           onClose={actions.closeAddStockModal}
409:           onAdd={actions.addStock}
410:           stockInfo={state.stockUpdateInfo}
411:         />
412:       )}
413:       {state.isThemeCustomizerOpen && (
414:         <ThemeCustomizerModal
415:           isOpen={state.isThemeCustomizerOpen}
416:           onClose={actions.closeThemeCustomizer}
417:           onSave={actions.saveCustomTheme}
418:           initialColors={state.customColors}
419:           editingTheme={state.editingCustomTheme}
420:         />
421:       )}
422:       {state.isImportModalOpen && (
423:         <ImportModal
424:           isOpen={state.isImportModalOpen}
425:           onClose={actions.closeImportModal}
426:           onImportMachines={actions.importMachines}
