/** @type {import('next').NextConfig} */
const nextConfig = {
  // Export the app as a fully static site that Electron can load without a server.
  output: "export",
  trailingSlash: true,
  images: {
    // Image optimization requires a server; disable it for the static export.
    unoptimized: true,
  },
  env: {
    API_KEY: process.env.GOOGLE_AI_API_KEY,
    GEMINI_API_KEY: process.env.GOOGLE_AI_API_KEY,
  },
};

module.exports = nextConfig;

// Electron main process for Heavy-Care Desktop
const { app, BrowserWindow, Menu, shell } = require("electron");
const http = require("http");
const fs = require("fs");
const path = require("path");

const isDev = !!process.env.ELECTRON_RENDERER_URL;

let mainWindow = null;
let staticServer = null;

// ---------------------------------------------------------------------------
// Tiny static file server to serve the exported Next.js app (out/) over
// localhost so absolute asset paths (/_next/...) resolve correctly without
// needing internet access or a custom protocol.
// ---------------------------------------------------------------------------
function startStaticServer(rootDir, port = 0) {
  return new Promise((resolve, reject) => {
    const mimeTypes = {
      ".html": "text/html",
      ".js": "text/javascript",
      ".mjs": "text/javascript",
      ".css": "text/css",
      ".json": "application/json",
      ".svg": "image/svg+xml",
      ".png": "image/png",
      ".jpg": "image/jpeg",
      ".jpeg": "image/jpeg",
      ".gif": "image/gif",
      ".webp": "image/webp",
      ".ico": "image/x-icon",
      ".woff": "font/woff",
      ".woff2": "font/woff2",
      ".ttf": "font/ttf",
      ".map": "application/json",
      ".wasm": "application/wasm",
    };

    const server = http.createServer((req, res) => {
      try {
        const url = new URL(req.url, `http://localhost:${port}`);
        let pathname = decodeURIComponent(url.pathname);

        // Block path traversal
        const safePath = path.normalize(pathname).replace(/^(\.\.[/\\])+/, "");
        let filePath = path.join(rootDir, safePath);

        if (!filePath.startsWith(rootDir)) {
          res.writeHead(403);
          return res.end("Forbidden");
        }

        if (pathname === "/" || !fs.existsSync(filePath)) {
          filePath = path.join(rootDir, "index.html");
        }

        const stat = fs.statSync(filePath);
        if (stat.isDirectory()) {
          filePath = path.join(filePath, "index.html");
        }

        const ext = path.extname(filePath).toLowerCase();
        res.writeHead(200, {
          "Content-Type": mimeTypes[ext] || "application/octet-stream",
          "Cache-Control": "no-cache",
        });
        fs.createReadStream(filePath).pipe(res);
      } catch (err) {
        res.writeHead(404);
        res.end("Not found");
      }
    });

    server.on("error", reject);
    server.listen(port, "127.0.0.1", () => resolve(server));
  });
}

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 900,
    minHeight: 600,
    backgroundColor: "#f8fafc",
    title: "HeavyCare",
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
    },
  });

  // External links open in the system browser instead of a new Electron window
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: "deny" };
  });

  if (isDev) {
    mainWindow.loadURL(process.env.ELECTRON_RENDERER_URL);
    mainWindow.webContents.openDevTools();
  } else {
    mainWindow.loadURL("http://127.0.0.1:48620/");
  }
}

app.whenReady().then(async () => {
  app.setAppUserModelId("com.heavycare.desktop");

  if (!isDev) {
    const outDir = path.join(process.cwd(), "renderer", "out");
    if (!fs.existsSync(path.join(outDir, "index.html"))) {
      // Fallback: packaged app ships out/ inside asar
      const asarDir = path.join(__dirname, "..", "renderer", "out");
      if (fs.existsSync(path.join(asarDir, "index.html"))) {
        staticServer = await startStaticServer(asarDir, 48620);
      } else {
        // Hardcoded port used below; if neither dir exists the window shows an error
        staticServer = await startStaticServer(outDir, 48620).catch(() => null);
      }
      if (staticServer) {
        await startStaticServer;
      }
    }
  }

  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on("window-all-closed", () => {
  if (staticServer) staticServer.close();
  if (process.platform !== "darwin") app.quit();
});

// Electron main process for Heavy-Care Desktop
const { app, BrowserWindow, shell } = require("electron");
const http = require("http");
const fs = require("fs");
const path = require("path");

// In dev, set ELECTRON_RENDERER_URL (e.g. http://localhost:5555) to load the
// Next.js dev server instead of the static export.
const isDev = !!process.env.ELECTRON_RENDERER_URL;

const STATIC_PORT = 48620;

let mainWindow = null;
let staticServer = null;

// ---------------------------------------------------------------------------
// Tiny static file server to serve the exported Next.js app (renderer/out/)
// over localhost so absolute asset paths (/_next/...) resolve correctly while
// staying fully offline.
// ---------------------------------------------------------------------------
function createStaticServer(rootDir, port) {
  const mimeTypes = {
    ".html": "text/html",
    ".js": "text/javascript",
    ".mjs": "text/javascript",
    ".css": "text/css",
    ".json": "application/json",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".ico": "image/x-icon",
    ".woff": "font/woff",
    ".woff2": "font/woff2",
    ".ttf": "font/ttf",
    ".map": "application/json",
    ".wasm": "application/wasm",
  };

  const server = http.createServer((req, res) => {
    try {
      const url = new URL(req.url, `http://127.0.0.1:${port}`);
      const pathname = decodeURIComponent(url.pathname);

      const safePath = path.normalize(pathname).replace(/^(\.\.[/\\])+/, "");
      let filePath = path.join(rootDir, safePath);

      if (!filePath.startsWith(rootDir)) {
        res.writeHead(403);
        return res.end("Forbidden");
      }

      if (pathname === "/" || !fs.existsSync(filePath)) {
        filePath = path.join(rootDir, "index.html");
      }

      if (fs.statSync(filePath).isDirectory()) {
        filePath = path.join(filePath, "index.html");
      }

      const ext = path.extname(filePath).toLowerCase();
      res.writeHead(200, {
        "Content-Type": mimeTypes[ext] || "application/octet-stream",
        "Cache-Control": "no-cache",
      });
      fs.createReadStream(filePath).pipe(res);
    } catch (err) {
      res.writeHead(404);
      res.end("Not found");
    }
  });

  return server;
}

function startStaticServer(rootDir, port) {
  return new Promise((resolve, reject) => {
    const server = createStaticServer(rootDir, port);
    server.once("error", reject);
    server.listen(port, "127.0.0.1", () => resolve(server));
  });
}

function getOutDir() {
  // Works both when running from the desktop/ folder (dev) and when packaged:
  // <desktop>/electron/main.js -> <desktop>/renderer/out
  return path.join(__dirname, "..", "renderer", "out");
}

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 900,
    minHeight: 600,
    backgroundColor: "#f8fafc",
    title: "HeavyCare",
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
    },
  });

  // External links open in the system browser, never inside the app window
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: "deny" };
  });

  if (isDev) {
    mainWindow.loadURL(process.env.ELECTRON_RENDERER_URL);
    mainWindow.webContents.openDevTools({ mode: "detach" });
  } else {
    mainWindow.loadURL(`http://127.0.0.1:${STATIC_PORT}/`);
  }
}

app.whenReady().then(async () => {
  app.setAppUserModelId("com.heavycare.desktop");

  if (!isDev) {
    const outDir = getOutDir();
    if (!fs.existsSync(path.join(outDir, "index.html"))) {
      console.error(
        `Static build not found at: ${outDir}\n` +
          `Run "npm run renderer:build" inside the desktop folder first.`
      );
      app.quit();
      return;
    }
    staticServer = await startStaticServer(outDir, STATIC_PORT);
  }

  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on("window-all-closed", () => {
  if (staticServer) staticServer.close();
  if (process.platform !== "darwin") app.quit();
});

// Preload script: secure bridge between the renderer (UI) and Electron main.
// Database (SQLite) calls will be exposed here via contextBridge later.
const { contextBridge, ipcRenderer } = require("electron");

contextBridge.exposeInMainWorld("desktop", {
  isDesktop: true,
  platform: process.platform,
  versions: {
    electron: process.versions.electron,
    node: process.versions.node,
  },
  // Placeholder IPC helpers for the upcoming SQLite data layer:
  // - db.query(...)
  // - db.exec(...)
  // - sync.push/pull to Supabase
  invoke: (channel, payload) => ipcRenderer.invoke(channel, payload),
});

