// Preload script: secure bridge between the renderer (UI) and the Electron main
// process. Exposes a supabase-shaped database + auth API over IPC.
const { contextBridge, ipcRenderer } = require("electron");

contextBridge.exposeInMainWorld("desktop", {
  isDesktop: true,
  platform: process.platform,
  versions: {
    electron: process.versions.electron,
    node: process.versions.node,
  },

  // ---- Database ----
  db: {
    query: (req) => ipcRenderer.invoke("db:query", req),
    syncStatus: () => ipcRenderer.invoke("db:sync-status"),
    syncNow: () => ipcRenderer.invoke("db:sync-now"),
  },

  // ---- Auth (local, offline) ----
  auth: {
    getSession: () => ipcRenderer.invoke("auth:get-session"),
    signIn: (email, password) => ipcRenderer.invoke("auth:sign-in", { email, password }),
    signUp: (email, password) => ipcRenderer.invoke("auth:sign-up", { email, password }),
    signOut: () => ipcRenderer.invoke("auth:sign-out"),
    updatePassword: (password) => ipcRenderer.invoke("auth:update-password", { password }),
    onAuthChanged: (cb) => {
      const handler = (_evt, { event, session }) => cb(event, session);
      ipcRenderer.on("auth:changed", handler);
      return () => ipcRenderer.removeListener("auth:changed", handler);
    },
  },

  // Legacy generic invoke (kept for diagnostics)
  invoke: (channel, payload) => ipcRenderer.invoke(channel, payload),
});

// supabase-compatible shim for the offline desktop app.
// Talks to the local SQLite database over IPC (Electron preload) and to the
// local auth provider. The rest of the app keeps using the exact same
// supabase-js calls (`supabase.from(...)`, `supabase.auth.*`) with zero edits.
import type { Database } from "../types/supabase";

type Filter = { col: string; op: "eq"; val: any };

interface DesktopBridge {
  db: {
    query: (req: {
      action: "select" | "insert" | "update" | "delete" | "upsert";
      table: string;
      payload?: any;
      filters?: Filter[];
      onConflict?: string[];
      single?: boolean;
    }) => Promise<{ data: any; error: any }>;
    syncStatus: () => Promise<{ configured: boolean; pending: number }>;
    syncNow: () => Promise<any>;
  };
  auth: {
    getSession: () => Promise<any>;
    signIn: (email: string, password: string) => Promise<any>;
    signUp: (email: string, password: string) => Promise<any>;
    signOut: () => Promise<any>;
    updatePassword: (password: string) => Promise<any>;
    onAuthChanged: (cb: (event: string, session: any) => void) => () => void;
  };
}

function getBridge(): DesktopBridge | null {
  if (typeof window !== "undefined" && (window as any).desktop) {
    return (window as any).desktop as DesktopBridge;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Query builder — awaitable, chainable, covering the exact patterns used:
//   from(T).select("*")
//   from(T).select("*").eq(col, val)
//   from(T).select("*").eq(col, val).single()
//   from(T).insert(rows | row).select()
//   from(T).update(payload).eq(col, val) [.eq(...) xN]
//   from(T).delete().eq(col, val)
//   from(T).upsert(payload, { onConflict: "a, b" })
// ---------------------------------------------------------------------------
class QueryBuilder<T = any> {
  private table: string;
  private action: "select" | "insert" | "update" | "delete" | "upsert";
  private payload: any;
  private filters: Filter[] = [];
  private onConflict: string[] = [];
  private isSingle = false;
  private returnRows = false; // insert().select()
  private promise: Promise<{ data: any; error: any }> | null = null;

  constructor(
    table: string,
    action: QueryBuilder["action"],
    payload?: any,
    options?: { returnRows?: boolean }
  ) {
    this.table = table;
    this.action = action;
    this.payload = payload;
    if (options?.returnRows) this.returnRows = true;
  }

  eq(col: string, val: any): this {
    this.filters.push({ col, op: "eq", val });
    return this;
  }

  /** Only meaningful after `.eq()` chains or on its own */
  select(_columns: string = "*", _opts?: any): this {
    // On non-select verbs this signals "return affected rows"
    if (this.action !== "select") this.returnRows = true;
    return this;
  }

  single(): Promise<{ data: any; error: any }> {
    this.isSingle = true;
    return (this as unknown as PromiseLike<any>) as any;
  }

  upsert(
    payload: any,
    options?: { onConflict?: string }
  ): this {
    if (options?.onConflict) {
      this.onConflict = options.onConflict.split(",").map((c) => c.trim());
    }
    this.payload = payload;
    return this;
  }

  private exec(): Promise<{ data: any; error: any }> {
    if (this.promise) return this.promise;
    const bridge = getBridge();
    if (!bridge) {
      this.promise = Promise.resolve({
        data: null,
        error: { message: "Desktop bridge unavailable (window.desktop)." },
      });
      return this.promise;
    }
    const action =
      this.action === "delete"
        ? "delete"
        : this.action === "select" && this.filters.length
          ? "select"
          : this.action;
    this.promise = bridge.db
      .query({
        action: action as any,
        table: this.table,
        payload: this.payload,
        filters: this.filters,
        onConflict: this.onConflict,
        single: this.isSingle,
      })
      .then((res) => {
        if (res.error) return res;
        // select().eq().single() -> unwrap handled backend-side via single flag
        let data = res.data;
        if (this.single && data === null && this.action === "select" && this.filters.length) {
          data = (res.data as any) ?? null;
        }
        if (this.action === "select" && !this.isSingle) {
          data = data;
        }
        if (this.returnRows && this.action === "select" && data === null) {
          data = [];
        }
        return { data, error: null };
      });
    return this.promise;
  }

  then<TResult1 = any, TResult2 = never>(
    onfulfilled?: ((value: any) => TResult1 | PromiseLike<TResult1>) | null,
    onrejected?: ((reason: any) => TResult2 | PromiseLike<TResult2>) | null
  ): PromiseLike<TResult1 | TResult2> {
    return this.exec().then(onfulfilled, onrejected);
  }

  catch<TResult = never>(
    onrejected?: ((reason: any) => TResult | PromiseLike<TResult>) | null
  ): PromiseLike<any | TResult> {
    return this.exec().catch(onrejected);
  }

  finally(onfinally?: (() => void) | null): PromiseLike<any> {
    return this.exec().finally(onfinally) as any;
  }
}

// Extract "a, b" conflict strings on plain (non-builder) upsert calls:
// The builder handles this via .upsert(); plain .upsert() calls on
// update/delete were never used in the app.

// ---------------------------------------------------------------------------
// supabase-compatible client
// ---------------------------------------------------------------------------
function makeClient() {
  const bridge = getBridge();

  const from = (table: string) => new QueryBuilder(table, "select");

  from.toString = () => "[Function from]";

  const compact = {
    from: (table: string) => {
      // from() must return a "select builder":
      //  - select("*") chains
      //  - insert(...) / update(...) / delete() / upsert(...) switch the verb
      const selectBuilder = new QueryBuilder(table, "select");
      const proxy: any = new Proxy(selectBuilder, {
        get(target, prop, receiver) {
          if (prop === "upsert") {
            return (payload: any, options?: { onConflict?: string }) => {
              const b = new QueryBuilder(table, "upsert");
              return b.upsert.call({} as any, payload, options) ?? b.upsert(payload, options), (b as any).upsert(payload, options), b;
            };
          }
          return Reflect.get(target, prop, receiver);
        },
      });
      return proxy;
    },
  };

  // Simpler and safer than Proxy magic: explicit verb switcher
  function fromReal(table: string) {
    const selectBuilder = new QueryBuilder(table, "select") as any;
    selectBuilder.insert = (payload: any) => new QueryBuilder(table, "insert", payload);
    selectBuilder.update = (payload: any) => new QueryBuilder(table, "update", payload);
    selectBuilder.delete = () => new QueryBuilder(table, "delete");
    selectBuilder.upsert = (payload: any, options?: { onConflict?: string }) => {
      const b = new QueryBuilder(table, "upsert", payload);
      if (options?.onConflict) b.upsert(payload, options);
      return b;
    };
    return selectBuilder;
  }

  const auth = {
    async getSession() {
      if (!bridge) return { data: { session: null }, error: null };
      return bridge.auth.getSession();
    },
    // Supabase listens via a subscription object
    onAuthStateChange(callback: (event: string, session: any) => void) {
      if (!bridge) {
        // Fire initial null session so the UI unblocks
        callback("INITIAL_SESSION", null);
        return { data: { subscription: { unsubscribe: () => {} } } };
      }
      // Emit the current session immediately (like supabase-js)
      bridge.auth.getSession().then((res) => {
        callback("INITIAL_SESSION", res?.data?.session ?? null);
      });
      const unsubscribe = bridge.auth.onAuthChanged((event, session) => {
        callback(event, session);
      });
      return { data: { subscription: { unsubscribe } } };
    },
    async signInWithPassword({ email, password }: { email: string; password: string }) {
      if (!bridge) return { error: { message: "Desktop bridge unavailable." } };
      const res = await bridge.auth.signIn(email, password);
      if (res.error) return { error: res.error };
      return { data: { user: res.data?.user ?? null }, error: null };
    },
    async signUp({
      email,
      password,
    }: {
      email: string;
      password: string;
      options?: any;
    }) {
      if (!bridge) return { error: { message: "Desktop bridge unavailable." } };
      const res = await bridge.auth.signUp(email, password);
      if (res.error) return { error: res.error };
      return { data: { user: res.data?.user ?? null }, error: null };
    },
    async signOut() {
      if (!bridge) return { error: null };
      return bridge.auth.signOut();
    },
    async updateUser({ password }: { password: string }) {
      if (!bridge) return { error: { message: "Desktop bridge unavailable." } };
      const res = await bridge.auth.updatePassword(password);
      return res;
    },
    // OAuth isn't available offline — surface a friendly error
    async signInWithOAuth(_opts: any) {
      return {
        error: {
          message: "Connexion Google indisponible hors ligne. Utilisez email + mot de passe.",
        },
      };
    },
    async resetPasswordForEmail(_email: string, _opts?: any) {
      return { data: null, error: null };
    },
  };

  return { from: fromReal, auth };
}

export const supabase = makeClient() as any;

// Provide the original Database type for imports elsewhere
export type { Database };

// supabase-compatible shim for the offline desktop app.
// Talks to the local SQLite database over IPC (Electron preload) and to a
// local auth provider. The rest of the app keeps using the exact same
// supabase-js calls (`supabase.from(...)`, `supabase.auth.*`) with zero edits.
import type { Database } from "../types/supabase";

type Filter = { col: string; op: "eq"; val: any };

interface DesktopBridge {
  db: {
    query: (req: {
      action: "select" | "insert" | "update" | "delete" | "upsert";
      table: string;
      payload?: any;
      filters?: Filter[];
      onConflict?: string[];
      single?: boolean;
    }) => Promise<{ data: any; error: any }>;
    syncStatus: () => Promise<{ configured: boolean; pending: number }>;
    syncNow: () => Promise<any>;
  };
  auth: {
    getSession: () => Promise<any>;
    signIn: (email: string, password: string) => Promise<any>;
    signUp: (email: string, password: string) => Promise<any>;
    signOut: () => Promise<any>;
    updatePassword: (password: string) => Promise<any>;
    onAuthChanged: (cb: (event: string, session: any) => void) => () => void;
  };
}

function getBridge(): DesktopBridge | null {
  if (typeof window !== "undefined" && (window as any).desktop) {
    return (window as any).desktop as DesktopBridge;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Query builder — awaitable, chainable. Covers the exact patterns used by the
// app:
//   from(T).select("*")
//   from(T).select("*").eq(col, val)
//   from(T).select("*").eq(col, val).single()
//   from(T).insert(row | rows).select()
//   from(T).update(payload).eq(col, val)
//   from(T).delete().eq(col, val)
//   from(T).upsert(payload, { onConflict: "a, b" })
// ---------------------------------------------------------------------------
class QueryBuilder {
  private table: string;
  private action: "select" | "insert" | "update" | "delete" | "upsert";
  private payload: any;
  private filters: Filter[] = [];
  private onConflict: string[] = [];
  private isSingle = false;
  private returnRows = false;
  private execPromise: Promise<{ data: any; error: any }> | null = null;

  constructor(
    table: string,
    action: QueryBuilder["action"],
    payload?: any,
    options?: { returnRows?: boolean }
  ) {
    this.table = table;
    this.action = action;
    this.payload = payload;
    if (options?.returnRows) this.returnRows = true;
  }

  eq(col: string, val: any): this {
    this.filters.push({ col, op: "eq", val });
    return this;
  }

  select(_columns: string = "*", _opts?: any): this {
    // `.insert(...).select()` / `.update(...).select()` => return affected rows
    if (this.action !== "select") this.returnRows = true;
    return this;
  }

  single(): this {
    this.isSingle = true;
    return this;
  }

  private exec(): Promise<{ data: any; error: any }> {
    if (this.execPromise) return this.execPromise;
    const bridge = getBridge();
    if (!bridge) {
      this.execPromise = Promise.resolve({
        data: null,
        error: { message: "Desktop bridge unavailable (window.desktop)." },
      });
      return this.execPromise;
    }
    this.execPromise = bridge.db.query({
      action: this.action,
      table: this.table,
      payload: this.payload,
      filters: this.filters,
      onConflict: this.onConflict,
      single: this.isSingle,
    });
    return this.execPromise;
  }

  // PromiseLike so `await supabase.from(...)...` works everywhere
  then(
    onfulfilled?: ((value: any) => any) | null,
    onrejected?: ((reason: any) => any) | null
  ) {
    return this.exec().then(onfulfilled, onrejected);
  }

  catch(onrejected?: ((reason: any) => any) | null) {
    return this.exec().catch(onrejected);
  }

  finally(onfinally?: (() => void) | null) {
    return this.exec().finally(onfinally);
  }
}

// ---------------------------------------------------------------------------
// supabase-compatible client
// ---------------------------------------------------------------------------
function fromReal(table: string) {
  const selectBuilder: any = new QueryBuilder(table, "select");
  selectBuilder.insert = (payload: any) => new QueryBuilder(table, "insert", payload);
  selectBuilder.update = (payload: any) => new QueryBuilder(table, "update", payload);
  selectBuilder.delete = () => new QueryBuilder(table, "delete");
  selectBuilder.upsert = (payload: any, options?: { onConflict?: string }) => {
    const builder = new QueryBuilder(table, "upsert", payload);
    if (options?.onConflict) {
      // Re-apply with conflict columns captured
      builder["onConflict"] = options.onConflict
        .split(",")
        .map((c) => c.trim());
    }
    return builder;
  };
  return selectBuilder;
}

const auth = {
  async getSession() {
    const bridge = getBridge();
    if (!bridge) return { data: { session: null }, error: null };
    return bridge.auth.getSession();
  },
  onAuthStateChange(callback: (event: string, session: any) => void) {
    const bridge = getBridge();
    if (!bridge) {
      callback("INITIAL_SESSION", null);
      return { data: { subscription: { unsubscribe: () => {} } } };
    }
    bridge.auth.getSession().then((res) => {
      callback("INITIAL_SESSION", res?.data?.session ?? null);
    });
    const unsubscribe = bridge.auth.onAuthChanged((event, session) => {
      callback(event, session);
    });
    return { data: { subscription: { unsubscribe } } };
  },
  async signInWithPassword({ email, password }: { email: string; password: string }) {
    const bridge = getBridge();
    if (!bridge) return { error: { message: "Desktop bridge unavailable." } };
    const res = await bridge.auth.signIn(email, password);
    return res.error ? res : { data: res.data, error: null };
  },
  async signUp({
    email,
    password,
  }: {
    email: string;
    password: string;
    options?: any;
  }) {
    const bridge = getBridge();
    if (!bridge) return { error: { message: "Desktop bridge unavailable." } };
    const res = await bridge.auth.signUp(email, password);
    return res.error ? res : { data: res.data, error: null };
  },
  async signOut() {
    const bridge = getBridge();
    if (!bridge) return { error: null };
    return bridge.auth.signOut();
  },
  async updateUser({ password }: { password: string }) {
    const bridge = getBridge();
    if (!bridge) return { error: { message: "Desktop bridge unavailable." } };
    return bridge.auth.updatePassword(password);
  },
  // OAuth isn't available offline
  async signInWithOAuth(_opts: any) {
    return {
      error: {
        message: "Connexion Google indisponible hors ligne. Utilisez email + mot de passe.",
      },
    };
  },
  async resetPasswordForEmail(_email: string, _opts?: any) {
    return { data: null, error: null };
  },
};

export const supabase = { from: fromReal, auth };

// Keep the original Database type available for type-only imports
export type { Database };

