118: async fn ensure_token(sync: &Sync, auth: &crate::auth::Auth) -> Option<String> {
119:     if !sync.is_configured() {
120:         return None;
121:     }
122:     {
123:         let t = sync.token.lock().unwrap();
124:         if let (Some(tok), exp) = (&t.access_token, t.expiry_ms) {
125:             if chrono::Utc::now().timestamp_millis() < exp {
126:                 return Some(tok.clone());
127:             }
128:         }
129:     }
130:     // 1) The app's own Supabase session (user signed in via Google or password)
131:     if let Some(tok) = crate::auth::get_valid_token(auth).await {
132:         let mut t = sync.token.lock().unwrap();
133:         t.access_token = Some(tok.clone());
134:         t.expiry_ms = chrono::Utc::now().timestamp_millis() + 5 * 60 * 1000;
135:         return Some(tok);
136:     }
137:     // 2) Config file email/password fallback
138:     let conf = {
139:         let c = sync.conf.lock().unwrap();
140:         c.clone().unwrap_or_else(|| SyncConf {
141:             url: BUILTIN_URL.into(),
142:             anon_key: BUILTIN_ANON_KEY.into(),
143:             email: None,
144:             password: None,
145:         })
146:     };
147:     let (email, password) = match (&conf.email, &conf.password) {
148:         (Some(e), Some(p)) => (e.clone(), p.clone()),
149:         _ => return None,
150:     };
151:     let client = reqwest::Client::new();
152:     let res = client
153:         .post(format!("{}/auth/v1/token?grant_type=password", conf.url))
154:         .header("apikey", &conf.anon_key)
155:         .json(&json!({ "email": email, "password": password }))
156:         .send()
157:         .await
158:         .ok()?;
159:     if !res.status().is_success() {
160:         eprintln!("Supabase sign-in failed: {}", res.status());
161:         return None;
162:     }
163:     let data: Value = res.json().await.ok()?;
164:     let tok = data["access_token"].as_str()?.to_string();
165:     let expires_in = data["expires_in"].as_i64().unwrap_or(3600);
166:     {
167:         let mut t = sync.token.lock().unwrap();
168:         t.access_token = Some(tok.clone());
169:         t.expiry_ms = chrono::Utc::now().timestamp_millis() + (expires_in - 120) * 1000;
170:     }
171:     Some(tok)
172: }
