174: impl Sync {
175:     pub async fn rest(
176:         &self,
177:         auth: &crate::auth::Auth,
178:         method: &str,
179:         table: &str,
180:         query: &str,
181:         body: Option<Value>,
182:         prefer: Option<String>,
183:     ) -> Result<Value, String> {
184:         let (url, anon_key) = self.get_supplier_url_key();
185:         let token = ensure_token(self, auth).await;
186:         let auth_header = match &token {
187:             Some(t) => format!("Bearer {}", t),
188:             None => format!("Bearer {}", anon_key),
189:         };
190:         let client = reqwest::Client::new();
191:         let send = |client: &reqwest::Client, auth: String| {
192:             let mut req = client
193:                 .request(
194:                     reqwest::Method::from_bytes(method.as_bytes())
195:                         .unwrap_or(reqwest::Method::GET),
196:                     format!("{}/rest/v1/{}{}", url, table, query),
197:                 )
198:                 .header("apikey", &anon_key)
199:                 .header("Authorization", auth)
200:                 .header("Content-Type", "application/json");
201:             if let Some(p) = &prefer {
202:                 req = req.header("Prefer", p.clone());
203:             }
204:             if let Some(b) = &body {
205:                 req = req.body(b.to_string());
206:             }
207:             req.send()
208:         };
209:         let res = send(&client, auth_header).await.map_err(|e| e.to_string())?;
210:         if res.status().as_u16() == 401 && token.is_some() {
211:             // token expired mid-flight -> re-auth once and retry
212:             {
213:                 let mut t = self.token.lock().unwrap();
214:                 t.access_token = None;
215:                 t.expiry_ms = 0;
216:             }
217:             let new_tok = ensure_token(self, auth).await;
218:             if let Some(nt) = new_tok {
219:                 let res2 = send(&client, format!("Bearer {}", nt))
220:                     .await
221:                     .map_err(|e| e.to_string())?;
222:                 let status = res2.status().as_u16();
223:                 let text = res2.text().await.unwrap_or_default();
224:                 if !(200..300).contains(&status) {
225:                     return Err(format!("{} {} -> {} {}", method, table, status, text));
226:                 }
227:                 return Ok(serde_json::from_str::<Value>(&text).unwrap_or(json!(text)));
228:             }
229:         }
230:         let status = res.status().as_u16();
231:         let text = res.text().await.unwrap_or_default();
232:         if !(200..300).contains(&status) {
233:             return Err(format!("{} {} -> {} {}", method, table, status, text));
234:         }
235:         Ok(serde_json::from_str(&text).unwrap_or(json!(text)))
236:     }
237: }
