239: pub async fn run_sync(sync: &Sync, db: &db::Db, auth: &crate::auth::Auth) -> Value {
240:     if !sync.is_configured() {
241:         return json!({ "ok": false, "status": "not-configured" });
242:     }
243:     if sync
244:         .syncing
245:         .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
246:         .is_err()
247:     {
248:         return json!({ "ok": false, "status": "in-progress" });
249:     }
250:     let result = run_sync_inner(sync, db, auth).await;
251:     sync.syncing.store(false, Ordering::SeqCst);
252:     result
253: }
