255: async fn run_sync_inner(sync: &Sync, db: &db::Db, auth: &crate::auth::Auth) -> Value {
256:     // Never push/pull without an authenticated token — anon requests see
257:     // nothing through RLS and would advance the watermark while missing data.
258:     let app_token = crate::auth::get_valid_token(auth).await;
259:     let has_config_creds;
260:     {
261:         let c = sync.conf.lock().unwrap();
262:         has_config_creds = c
263:             .as_ref()
264:             .map(|c| c.email.is_some() && c.password.is_some())
265:             .unwrap_or(false);
266:     }
267:     if app_token.is_none() && !has_config_creds {
268:         return json!({ "ok": false, "status": "unauthenticated" });
269:     }
270:     sync.dirty.store(false, Ordering::SeqCst);
271: 
272:     let push = push_pending(sync, db, auth).await;
273:     let pull = pull_remote(sync, db, auth).await;
274:     sync.set_last_sync(db::now_iso());
275:     json!({
276:         "ok": push["error"].is_null() && pull["error"].is_null(),
277:         "status": "done",
278:         "push": push,
279:         "pull": pull
280:     })
281: }
