285: async fn push_pending(sync: &Sync, db: &db::Db, auth: &crate::auth::Auth) -> Value {
286:     let pending = db::pending_queue(db, "", &[]);
287:     let mut pushed = 0usize;
288:     for item in pending {
289:         let table = item["table_name"].as_str().unwrap_or_default().to_string();
290:         let op = item["op"].as_str().unwrap_or_default().to_string();
291:         let row_id = item["row_id"].as_str().unwrap_or_default().to_string();
292:         let seq = item["seq"].as_i64().unwrap_or(0);
293:         let payload = if item["payload"].is_null() {
294:             None
295:         } else {
296:             serde_json::from_str::<Value>(item["payload"].as_str().unwrap_or_default()).ok()
297:         };
298:         let res = if op == "delete" {
299:             sync.rest(
300:                 auth,
301:                 "DELETE",
302:                 &table,
303:                 &format!("?id=eq.{}", row_id),
304:                 None,
305:                 None,
306:             )
307:             .await
308:         } else {
309:             // upsert by primary key (resolution=merge-duplicates)
310:             sync.rest(
311:                 auth,
312:                 "POST",
313:                 &table,
314:                 "",
315:                 payload.map(|p| json!([p])),
316:                 Some("return=minimal,resolution=merge-duplicates".to_string()),
317:             )
318:             .await
319:         };
320:         match res {
321:             Ok(_) => {
322:                 db::mark_synced(db, seq);
323:                 pushed += 1;
324:             }
325:             Err(e) => {
326:                 eprintln!("Sync push failed ({}/{}): {}", table, row_id, e);
327:                 return json!({ "pushed": 0, "error": e });
328:             }
329:         }
330:     }
331:     json!({ "pushed": pushed, "error": Value::Null })
332: }
