334: async fn pull_remote(sync: &Sync, db: &db::Db, auth: &crate::auth::Auth) -> Value {
335:     let mut error: Option<String> = None;
336:     let mut total_rows = 0usize;
337:     let mut rows_applied = 0usize;
338: 
339:     for table in db::SYNCED_TABLES {
340:         let table = table.to_string();
341:         let remote = match sync.rest(auth, "GET", &table, "?select=*", None, None).await {
342:             Ok(v) => v,
343:             Err(e) => {
344:                 eprintln!("Sync pull failed ({}): {}", table, e);
345:                 error = Some(e);
346:                 continue;
347:             }
348:         };
349:         let rows = remote.as_array().cloned().unwrap_or_default();
350:         total_rows += rows.len();
351: 
352:         for row in rows {
353:             let row_id = row["id"].as_str().unwrap_or_default().to_string();
354:             let existing = db::query_one(db, &table, "id = ?", &[json!(row_id)]);
355:             match existing {
356:                 None => {
357:                     if db::insert_row(db, &table, &row, false).is_some() {
358:                         rows_applied += 1;
359:                     }
360:                 }
361:                 Some(ex) => {
362:                     let remote_at = row["updated_at"].as_str().unwrap_or_default();
363:                     let existing_at = ex["updated_at"].as_str().unwrap_or_default();
364:                     if !remote_at.is_empty()
365:                         && !existing_at.is_empty()
366:                         && parse_ts(remote_at) > parse_ts(existing_at)
367:                     {
368:                         let filters = json!([{ "col": "id", "op": "eq", "val": row_id }]);
369:                         let _ = db::update_row(db, &table, &row, Some(filters), false);
370:                         rows_applied += 1;
371:                     }
372:                 }
373:             }
374:         }
375: 
376:         // Detect remote deletions: full remote id list; drop local rows that
377:         // vanish from it unless they are still pending to push.
378:         let id_list = match sync.rest(auth, "GET", &table, "?select=id", None, None).await {
379:             Ok(v) => v,
380:             Err(_) => continue,
381:         };
382:         let remote_ids: std::collections::HashSet<String> = id_list
383:             .as_array()
384:             .map(|a| {
385:                 a.iter()
386:                     .filter_map(|r| r["id"].as_str().map(|s| s.to_string()))
387:                     .collect()
388:             })
389:             .unwrap_or_default();
390:         let bind = json!(table);
391:         let pending = db::pending_queue(db, "table_name = ?", &[bind]);
392:         let local_pending: std::collections::HashSet<String> = pending
393:             .iter()
394:             .filter_map(|q| q["row_id"].as_str().map(|s| s.to_string()))
395:             .collect();
396:         let locals = db::query_all(db, &table, "", &[]);
397:         for local in locals {
398:             let lid = local["id"].as_str().unwrap_or_default().to_string();
399:             if remote_ids.contains(&lid) || local_pending.contains(&lid) {
400:                 continue;
401:             }
402:             let filters = json!([{ "col": "id", "op": "eq", "val": lid }]);
403:             if db::delete_row(db, &table, Some(filters), false).is_ok() {
404:                 rows_applied += 1;
405:             }
406:         }
407:     }
408: 
409:     eprintln!(
410:         "Sync pull complete: {} rows across {} tables, {} changes applied locally.",
411:         total_rows,
412:         db::SYNCED_TABLES.len(),
413:         rows_applied
414:     );
415:     json!({ "error": error, "rowsApplied": rows_applied })
416: }
