418: // JS `new Date(...).getTime()` comparator: ISO-8601 strings compare lexically
419: // only if formats match; Supabase returns RFC3339 with offset. Parse properly.
420: fn parse_ts(s: &str) -> i64 {
421:     chrono::DateTime::parse_from_rfc3339(s)
422:         .map(|d| d.timestamp_millis())
423:         .unwrap_or_else(|_| {
424:             chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.f")
425:                 .ok()
426:                 .map(|n| n.and_utc().timestamp_millis())
427:                 .unwrap_or(i64::MIN)
428:         })
429: }

