209: async fn handle_callback_conn(app: Arc<AppCtx>, mut stream: tokio::net::TcpStream) {
210:     use tokio::io::{AsyncReadExt, AsyncWriteExt};
211:     let mut buf = [0u8; 4096];
212:     let n = stream.read(&mut buf).await.unwrap_or(0);
213:     let req_text = String::from_utf8_lossy(&buf[..n]).to_string();
214:     let first_line = req_text.lines().next().unwrap_or_default().to_string();
215:     // e.g. "GET /auth/callback?code=... HTTP/1.1"
216:     let raw_path = first_line
217:         .split_whitespace()
218:         .nth(1)
219:         .unwrap_or_default()
220:         .to_string();
221: 
222:     let body = if raw_path.starts_with("/auth/callback") {
223:         let query = raw_path.split('?').nth(1).unwrap_or_default();
224:         let mut code = String::new();
225:         let mut err_desc = String::new();
226:         for pair in query.split('&') {
227:             let mut it = pair.splitn(2, '=');
228:             let k = it.next().unwrap_or_default();
229:             let v = urldecode(it.next().unwrap_or_default());
230:             match k {
231:                 "code" => code = v,
232:                 "error_description" | "error" => err_desc = v,
233:                 _ => {}
234:             }
235:         }
236:         if !code.is_empty() {
237:             // Bind the take() result first so no MutexGuard is held across await
238:             let verifier: Option<String> = app.pending_verifier.lock().unwrap().take();
239:             if let Some(verifier) = verifier {
240:                 match auth::exchange_code(&app.auth, &code, &verifier).await {
241:                     Ok(()) => {
242:                         eprintln!("Supabase session established (OAuth).");
243:                         app.app_handle
244:                             .emit(
245:                                 "auth:changed",
246:                                 json!({ "event": "SIGNED_IN", "session": get_active_session(&app) }),
247:                             )
248:                             .ok();
249:                     }
250:                     Err(e) => eprintln!("OAuth exchange failed: {}", e),
251:                 }
252:             }
253:         }
254:         let message = if code.is_empty() {
255:             format!(
256:                 "<p>Connexion échouée : {}. Vous pouvez fermer cette fenêtre.</p>",
257:                 if err_desc.is_empty() { "aucun code reçu" } else { &err_desc }
258:             )
259:         } else {
260:             "<p>Connexion réussie. Vous pouvez fermer cette fenêtre…</p>".to_string()
261:         };
262:         format!(
263:             "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n<!DOCTYPE html><html><head><style>body{{font-family:sans-serif;display:flex;align-items:center;justify-content:center;height:100vh;margin:0;color:#0f172a}}</style></head><body>{}<script>setTimeout(()=>window.close(),800)</script></body></html>",
264:             message.len(),
265:             message
266:         )
267:     } else {
268:         "HTTP/1.1 404 Not Found\r\nContent-Length: 9\r\nConnection: close\r\n\r\nNot found"
269:             .to_string()
270:     };
271: 
272:     let _ = stream.write_all(body.as_bytes()).await;
273:     let _ = stream.flush().await;
274:     stream.shutdown().await.ok();
275: }
