277: fn urldecode(s: &str) -> String {
278:     let bytes = s.as_bytes();
279:     let mut out = Vec::new();
280:     let mut i = 0;
281:     while i < bytes.len() {
282:         match bytes[i] {
283:             b'%' if i + 2 < bytes.len() => {
284:                 let h = u8::from_str_radix(&s[i + 1..i + 3], 16).unwrap_or(b'%');
285:                 out.push(h);
286:                 i += 3;
287:             }
288:             b'+' => {
289:                 out.push(b' ');
290:                 i += 1;
291:             }
292:             b => {
293:                 out.push(b);
294:                 i += 1;
295:             }
296:         }
297:     }
298:     String::from_utf8_lossy(&out).to_string()
299: }
