    "proname": "has_chantier_access",
    "def": "CREATE OR REPLACE FUNCTION public.has_chantier_access(chantier_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  RETURN EXISTS (\n    SELECT 1 FROM user_chantiers\n    WHERE user_id = auth.uid()\n      AND user_chantiers.chantier_id = $1\n  );\nEND;\n$function$\n"
  },
  {
    "proname": "auto_assign_chantier",
    "def": "CREATE OR REPLACE FUNCTION public.auto_assign_chantier()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nBEGIN\n  INSERT INTO public.user_chantiers (user_id, chantier_id)\n  VALUES (NEW.id, '00000000-0000-0000-0000-000000000001')\n  ON CONFLICT DO NOTHING;\n  RETURN NEW;\nEND;\n$function$\n"
  },
  {
    "proname": "verify_chantier_password",
    "def": "CREATE OR REPLACE FUNCTION public.verify_chantier_password(chantier_id uuid, password text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE\n  hash TEXT;\nBEGIN\n  SELECT password_hash INTO hash FROM public.chantiers WHERE id = $1;\n  IF hash IS NULL THEN\n    RETURN TRUE;\n  END IF;\n  RETURN crypt($2, hash) = hash;\nEND;\n$function$\n"
  },
  {
    "proname": "set_chantier_password",
    "def": "CREATE OR REPLACE FUNCTION public.set_chantier_password(chantier_id uuid, password text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nBEGIN\n  IF NOT public.has_chantier_access($1) THEN\n    RETURN FALSE;\n  END IF;\n  IF $2 IS NULL OR $2 = '' THEN\n    UPDATE public.chantiers SET password_hash = NULL WHERE id = $1;\n  ELSE\n    UPDATE public.chantiers SET password_hash = crypt($2, gen_salt('bf')) WHERE id = $1;\n  END IF;\n  RETURN TRUE;\nEND;\n$function$\n"
  },
  {
    "proname": "is_super_admin",
    "def": "CREATE OR REPLACE FUNCTION public.is_super_admin()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nBEGIN\r\n  RETURN EXISTS (\r\n    SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'super_admin'\r\n  );\r\nEND;\r\n$function$\n"
  },
  {
    "proname": "has_pole_access",
    "def": "CREATE OR REPLACE FUNCTION public.has_pole_access(pole_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nBEGIN\r\n  IF is_super_admin() THEN RETURN TRUE; END IF;\r\n  RETURN EXISTS (\r\n    SELECT 1 FROM profiles WHERE id = auth.uid() AND pole_id = $1\r\n  );\r\nEND;\r\n$function$\n"
  },
  {
    "proname": "set_updated_at",
    "def": "CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$function$\n"
  },
  {
    "proname": "update_updated_at_column",
    "def": "CREATE OR REPLACE FUNCTION public.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$\n"
  }
]

