/**
 * Poles CRUD. Privileges: RLS on `poles` allows super admins to
 * insert/update/delete (delete only when archived_at IS NOT NULL), so all
 * operations here run directly from the browser with the anon key — no
 * service-role key is ever used client-side.
 */
export default function PolesPage() {
  const [poles, setPoles] = useState<Pole[]>([]);
  const [stats, setStats] = useState<PoleStats[]>([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [notif, setNotif] = useState<{ msg: string; kind: 'ok' | 'err' } | null>(null);

  // create form
  const [newCode, setNewCode] = useState('');
  const [newName, setNewName] = useState('');
  const [busy, setBusy] = useState(false);
  // edits: pole_id -> {code, name}
  const [edits, setEdits] = useState<Record<string, { code: string; name: string }>>({});

  const say = (msg: string, kind: 'ok' | 'err' = 'ok') => {
    setNotif({ msg, kind });
    setTimeout(() => setNotif(null), 4000);
  };

  const load = async () => {
    try {
      const polesRes = await supabase
        .from('poles')
        .select('id, code, name, created_at, updated_at, archived_at')
        .order('code');
      if (polesRes.error) throw polesRes.error;

      const dbPoles = (polesRes.data ?? []) as Pole[];
      setPoles(dbPoles);
      setEdits(Object.fromEntries(dbPoles.map((p) => [p.id, { code: p.code, name: p.name }])));

      // Per-pole stats computed client-side (super admin reads across poles).
      const [usersRes, machinesRes] = await Promise.all([
        supabase.from('profiles').select('id, pole_id'),
        supabase.from('machines').select('id, pole_id'),
      ]);
      if (usersRes.error) throw usersRes.error;
      if (machinesRes.error) throw machinesRes.error;

      setStats(
        dbPoles.map((p) => ({
          pole_id: p.id,
          pole_code: p.code,
          pole_name: p.name,
          machine_count: machinesRes.data?.filter((m: any) => m.pole_id === p.id).length ?? 0,
          maintenance_count: 0,
          user_count: usersRes.data?.filter((u: any) => u.pole_id === p.id).length ?? 0,
        }))
      );
    } catch (e: any) {
      setErr(e.message ?? String(e));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const createPole = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCode.trim() || !newName.trim()) return;
    setBusy(true);
    const id = crypto.randomUUID();
    const { error } = await supabase
      .from('poles')
      .insert({ id, code: newCode.trim().toUpperCase(), name: newName.trim() });
    setBusy(false);
    if (error) {
      say(`Création refusée : ${error.message}`, 'err');
      return;
    }
    setNewCode('');
    setNewName('');
    say(`Pôle ${newCode.trim().toUpperCase()} créé.`);
    await load();
  };

  const saveEdits = async (pol: Pole) => {
    const edit = edits[pol.id];
    if (!edit) return;
    const { error } = await supabase
      .from('poles')
      .update({ code: edit.code.trim().toUpperCase(), name: edit.name.trim() })
      .eq('id', pol.id);
    if (error) {
      say(`Modification refusée : ${error.message}`, 'err');
      return;
    }
    say('Pôle modifié.');
    await load();
  };

  const setArchived = async (pol: Pole, archived: boolean) => {
    const { error } = await supabase
      .from('poles')
      .update({ archived_at: archived ? new Date().toISOString() : null })
      .eq('id', pol.id);
    if (error) {
      say(`Operation refusée : ${error.message}`, 'err');
      return;
    }
    say(archived ? 'Pôle archivé (désactivé).' : 'Pôle réactivé.');
    await load();
  };

  const deleteArchived = async (pol: Pole) => {
    if (!confirm(`Supprimer définitivement le pôle ${pol.code} ? Action irréversible.`)) return;
    const { error } = await supabase.from('poles').delete().eq('id', pol.id);
    if (error) {
      // The RLS policy deletes archived poles only; also reject if anything
      // still references this pole (FKs) — surface the message.
      say(`Suppression refusée : ${error.message}`, 'err');
      return;
    }
    say('Pôle supprimé.');
    await load();
  };

  if (loading) return <div className="loading">Chargement des pôles...</div>;

  return (
    <>
      <div className="page-header">
        <h1>Gestion des pôles</h1>
        <span>Chaque enregistrement métier appartient à exactement un pôle.</span>
      </div>

      <form className="inline-form card" onSubmit={createPole} style={{ marginBottom: 20 }}>
        <h2 style={{ width: '100%' }}>Nouveau pôle</h2>
        <label className="field">
          Code
          <input
            className="input"
            value={newCode}
            onChange={(e) => setNewCode(e.target.value)}
            placeholder="T200"
            maxLength={12}
          />
        </label>
        <label className="field" style={{ flex: 1, minWidth: 220 }}>
          Nom
          <input
            className="input"
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            placeholder="Chantier Sud"
          />
        </label>
        <button className="btn" disabled={busy || !newCode.trim() || !newName.trim()}>
          {busy ? 'Création...' : 'Créer le pôle'}
        </button>
      </form>

      {err && <div className="error card" style={{ marginBottom: 16 }}>Erreur : {err}</div>}

      <div className="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Code</th>
              <th>Nom</th>
              <th>Utilisateurs</th>
              <th>Engins</th>
              <th>Statut</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {poles.map((pol) => {
              const stat = stats.find((s) => s.pole_id === pol.id);
              const edit = edits[pol.id] ?? { code: pol.code, name: pol.name };
              return (
                <tr key={pol.id}>
                  <td>
                    {pol.archived_at ? (
                      <span className="pole-chip" style={{ opacity: 0.6 }}>{pol.code}</span>
                    ) : (
                      <input
                        className="input"
                        style={{ width: 90 }}
                        value={edit.code}
                        onChange={(e) => setEdits((s) => ({ ...s, [pol.id]: { ...edit, code: e.target.value } }))}
                      />
                    )}
                  </td>
                  <td>
                    {pol.archived_at ? (
                      pol.name
                    ) : (
                      <input
                        className="input"
                        style={{ width: 220 }}
                        value={edit.name}
                        onChange={(e) => setEdits((s) => ({ ...s, [pol.id]: { ...edit, name: e.target.value } }))}
                      />
                    )}
                  </td>
                  <td>{stat?.user_count ?? 0}</td>
                  <td>{stat?.machine_count ?? 0}</td>
                  <td>{pol.archived_at ? <span className="badge archived">Archivé</span> : <span className="badge ok">Actif</span>}</td>
                  <td>
                    <div className="row-actions">
                      {!pol.archived_at && (
                        <>
                          <button className="btn small" onClick={() => saveEdits(pol)}>Enregistrer</button>
                          <button className="btn small secondary" onClick={() => setArchived(pol, true)}>Archiver</button>
                        </>
                      )}
                      {pol.archived_at && (
                        <>
                          <button className="btn small secondary" onClick={() => setArchived(pol, false)}>Réactiver</button>
                          <button className="btn small danger-btn" onClick={() => deleteArchived(pol)}>Supprimer</button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {poles.length === 0 && !err && <div className="empty">Aucun pôle — créez le premier ci-dessus.</div>}
      </div>

      {notif && <div className={`notif ${notif.kind === 'ok' ? 'ok' : 'err'}`}>{notif.msg}</div>}
    </>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { adminRpc } from '@/lib/api';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import type { Pole } from '@/types';

type AdminUser = {
  id: string;
  email: string | null;
  role: 'super_admin' | 'pole_admin' | 'user';
  pole_id: string | null;
  pole_code: string | null;
  email_confirmed: boolean;
  last_sign_in_at: string | null;
  created_at: string | null;
};

/**
 * Users management. Email addresses and account creation live in
 * auth.users, which the anon key must never touch: every operation here
 * goes through the `admin-users` Edge Function (supabase/functions/),
 * which verifies the caller's role server-side and uses the service-role
 * key server-side only.
 */
export default function UsersPage() {
  const { user: me } = useAuth();
  const [users, setUsers] = useState<AdminUser[] | null>(null);
  const [poles, setPoles] = useState<Pole[]>([]);
  const [err, setErr] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [notif, setNotif] = useState<{ msg: string; kind: 'ok' | 'err' } | null>(null);

  // create form
  const [newEmail, setNewEmail] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newRole, setNewRole] = useState<'user' | 'pole_admin' | 'super_admin'>('user');
  const [newPole, setNewPole] = useState('');
  const [creating, setCreating] = useState(false);
  const [showCreate, setShowCreate] = useState(false);

  const say = (msg: string, kind: 'ok' | 'err' = 'ok') => {
    setNotif({ msg, kind });
    setTimeout(() => setNotif(null), 4500);
  };

  const load = async () => {
    try {
      const list = await adminRpc<AdminUser[]>('list');
      setUsers(list);
      const polesRes = await supabase.from('poles').select('id, code, name').order('code');
      if (polesRes.error) throw polesRes.error;
      setPoles((polesRes.data ?? []) as Pole[]);
    } catch (e: any) {
      setErr(e.message ?? String(e));
    }
  };

  useEffect(() => {
    load();
  }, []);

  const act = async (id: string, fn: () => Promise<unknown>, okMsg: string) => {
    setBusyId(id);
    try {
      await fn();
      say(okMsg);
      await load();
    } catch (e: any) {
      say(e.message ?? String(e), 'err');
    } finally {
      setBusyId(null);
    }
  };

  const setRole = (id: string, role: AdminUser['role']) =>
    act(id, () => adminRpc('set_role', { user_id: id, role }), 'Rôle modifié.');

  const setPole = (id: string, pole_id: string | null) =>
    act(id, () => adminRpc('assign_pole', { user_id: id, pole_id }), pole_id ? 'Pôle attribué.' : 'Pôle retiré.');

  const removeUser = (id: string, email: string | null) => {
    if (!confirm(`Supprimer définitivement le compte ${email ?? id} ? Action irréversible.`)) return;
    return act(id, () => adminRpc('delete_user', { user_id: id }), 'Compte supprimé.');
  };

  const createUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setCreating(true);
    try {
      await adminRpc('create', {
        email: newEmail.trim(),
        password: newPassword,
        role: newRole,
        pole_id: newPole || null,
      });
      say(`Compte ${newEmail.trim()} créé.`);
      setNewEmail('');
      setNewPassword('');
      setNewRole('user');
      setNewPole('');
      setShowCreate(false);
      await load();
    } catch (e: any) {
      say(e.message ?? String(e), 'err');
    } finally {
      setCreating(false);
    }
  };

  return (
    <>
      <div className="page-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h1>Utilisateurs</h1>
          <span>Rôles et pôles — gérés côté serveur (la clé de service ne quitte jamais le serveur).</span>
        </div>
        <button className="btn" onClick={() => setShowCreate((v) => !v)}>
          {showCreate ? 'Annuler' : '+ Créer un compte'}
        </button>
      </div>

      {showCreate && (
        <form className="inline-form card" onSubmit={createUser} style={{ marginBottom: 20 }}>
          <h2 style={{ width: '100%' }}>Nouveau compte</h2>
          <label className="field" style={{ flex: 1, minWidth: 240 }}>
            Email
            <input
              className="input"
              type="email"
              required
              value={newEmail}
              onChange={(e) => setNewEmail(e.target.value)}
              placeholder="prenom.nom@exemple.com"
            />
          </label>
          <label className="field">
            Mot de passe
            <input
              className="input"
              type="text"
              required
              minLength={6}
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              placeholder="6 caractères min."
            />
          </label>
          <label className="field">
            Rôle
            <select className="input" value={newRole} onChange={(e) => setNewRole(e.target.value as any)}>
              <option value="user">user</option>
              <option value="pole_admin">pole_admin</option>
              <option value="super_admin">super_admin</option>
            </select>
          </label>
          <label className="field">
            Pôle
            <select className="input" value={newPole} onChange={(e) => setNewPole(e.target.value)}>
              <option value="">— aucun —</option>
              {poles.filter((p) => !p.archived_at).map((pol) => (
                <option key={pol.id} value={pol.id}>{pol.code} — {pol.name}</option>
              ))}
            </select>
          </label>
          <button className="btn" disabled={creating}>
            {creating ? 'Création...' : 'Créer'}
          </button>
          <span style={{ width: '100%', color: 'var(--muted)', fontSize: '0.83rem' }}>
            Sans pôle, le nouveau compte voit « Compte sans pôle » dans l&apos;application jusqu&apos;à attribution.
          </span>
        </form>
      )}

      {err && <div className="error card" style={{ marginBottom: 16 }}>
        Edge Function « admin-users » injoignable : {err}
        <div style={{ color: 'var(--muted)', fontWeight: 400, marginTop: 6 }}>
          Déployez-la d&apos;abord : <code>supabase functions deploy admin-users --project-ref yklkxvvoeovksyslcfjy</code> (voir apps/admin/README.md).
        </div>
      </div>}

      <div className="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Email</th>
              <th>Rôle</th>
              <th>Pôle</th>
              <th>Email confirmé</th>
              <th>Dernière connexion</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {(users ?? []).map((u) => (
              <tr key={u.id}>
                <td>{u.email ?? <span className="unassigned">—</span>}</td>
                <td>
                  <select
                    className="input"
                    value={u.role}
                    disabled={busyId === u.id || u.id === me?.id}
                    onChange={(e) => setRole(u.id, e.target.value as AdminUser['role'])}
                  >
                    <option value="user">user</option>
                    <option value="pole_admin">pole_admin</option>
                    <option value="super_admin">super_admin</option>
                  </select>
                </td>
                <td>
                  {u.role === 'super_admin' ? (
                    <span className="unassigned">tous les pôles</span>
                  ) : (
                    <select
                      className="input"
                      value={u.pole_id ?? ''}
                      disabled={busyId === u.id}
                      onChange={(e) => setPole(u.id, e.target.value || null)}
                    >
                      <option value="">— aucun —</option>
                      {poles.map((pol) => (
                        <option key={pol.id} value={pol.id}>
                          {pol.code}{pol.archived_at ? ' (archivé)' : ''}
                        </option>
                      ))}
                    </select>
                  )}
                </td>
                <td>{u.email_confirmed ? <span className="badge ok">Oui</span> : <span className="badge wait">Non</span>}</td>
                <td style={{ color: 'var(--muted)' }}>
                  {u.last_sign_in_at ? u.last_sign_in_at.slice(0, 16).replace('T', ' ') : '—'}
                </td>
                <td>
                  <div className="row-actions">
                    {u.id !== me?.id && (
                      <button
                        className="btn small danger-btn"
                        disabled={busyId === u.id}
                        onClick={() => removeUser(u.id, u.email)}
                      >
                        Supprimer
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {users && users.length === 0 && !err && <div className="empty">Aucun compte.</div>}
        {!users && !err && <div className="loading">Chargement des comptes...</div>}
      </div>

      {notif && <div className={`notif ${notif.kind === 'ok' ? 'ok' : 'err'}`}>{notif.msg}</div>}
    </>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';
import type { Pole } from '@/types';

type Row = { pole: string; label: string; machines: number; records: number; downtime: number };

/**
 * Cross-pole statistics for the super admin. All counts come from the
 * business tables (RLS lets super admins read every pole); they are
 * aggregated client-side — the data volume stays small (356 rows at the
 * time of writing), no server aggregation needed for now.
 */
export default function StatisticsPage() {
  const [rows, setRows] = useState<Row[] | null>(null);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      try {
        const [polesRes, machinesRes, recordsRes, adjustmentsRes] = await Promise.all([
          supabase.from('poles').select('id, code, name').order('code'),
          supabase.from('machines').select('pole_id'),
          supabase.from('maintenance_records').select('pole_id, downtime_hours'),
          supabase.from('monthly_daily_adjustments').select('pole_id, downtime_hours'),
        ]);
        if (polesRes.error) throw polesRes.error;
        if (machinesRes.error) throw machinesRes.error;
        if (recordsRes.error) throw recordsRes.error;
        if (adjustmentsRes.error) throw adjustmentsRes.error;

        setRows(
          ((polesRes.data ?? []) as Pole[]).map((pol) => ({
            pole: pol.code,
            label: pol.name,
            machines: machinesRes.data?.filter((m: any) => m.pole_id === pol.id).length ?? 0,
            records: recordsRes.data?.filter((r: any) => r.pole_id === pol.id).length ?? 0,
            downtime:
              adjustmentsRes.data
                ?.filter((a: any) => a.pole_id === pol.id)
                .reduce((sum: number, a: any) => sum + (a.downtime_hours ?? 0), 0) ?? 0,
          }))
        );
      } catch (e: any) {
        setErr(e.message ?? String(e));
      }
    })();
  }, []);

  const bar = (value: number, max: number) => (
    <div className="bar-row">
      <div className="bar-track">
        <div className="bar-fill" style={{ width: max > 0 ? `${Math.max(2, (value / max) * 100)}%` : '2%' }} />
      </div>
    </div>
  );

  const maxMachines = Math.max(...(rows?.map((r) => r.machines) ?? [0]), 1);
  const maxRecords = Math.max(...(rows?.map((r) => r.records) ?? [0]), 1);
  const maxDowntime = Math.max(...(rows?.map((r) => r.downtime) ?? [0]), 1);

  if (err) return <div className="error card">Erreur : {err}</div>;
  if (!rows) return <div className="loading">Calcul des statistiques...</div>;

  return (
    <>
      <div className="page-header">
        <h1>Statistiques</h1>
        <span>Comparaison entre pôles — agrégée côté client (lecture super admin).</span>
      </div>

      <div className="grid-2">
        <div className="card">
          <h2 style={{ marginBottom: 12 }}>Engins par pôle</h2>
          {rows.map((r) => (
            <div key={r.pole}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem' }}>
                <strong>{r.pole}</strong><span>{r.machines}</span>
              </div>
              {bar(r.machines, maxMachines)}
            </div>
          ))}
        </div>

        <div className="card">
          <h2 style={{ marginBottom: 12 }}>Maintenances par pôle</h2>
          {rows.map((r) => (
            <div key={r.pole}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem' }}>
                <strong>{r.pole}</strong><span>{r.records}</span>
              </div>
              {bar(r.records, maxRecords)}
            </div>
          ))}
        </div>

        <div className="card">
          <h2 style={{ marginBottom: 12 }}>Heures d&apos;immobilisation (réglages journaliers)</h2>
          {rows.map((r) => (
            <div key={r.pole}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem' }}>
                <strong>{r.pole}</strong><span>{r.downtime.toFixed(1)} h</span>
              </div>
              {bar(r.downtime, maxDowntime)}
            </div>
          ))}
        </div>
      </div>
    </>
  );
}

// Edge Function: admin-users
//
// Single privileged gateway for the admin panel's user management. The
// service-role key lives ONLY here (server-side); the browser sends the
// caller's personal session JWT and nothing else. Every request is:
//   1. JWT-verified (platform verify_jwt + explicit getUser),
//   2. role-checked against `profiles` (must be super_admin),
// before any action runs.
//
// Deploy (once, then after each change):
//   supabase functions deploy admin-users --project-ref yklkxvvoeovksyslcfjy
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS, 'Content-Type': 'application/json' },
  });
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: CORS });
  }

  // ---- authenticate the CALLER (not service role yet) ----
  const authz = req.headers.get('Authorization') ?? '';
  const jwt = authz.replace(/^Bearer\s+/i, '').trim();
  if (!jwt) return json({ error: 'Jeton manquant.' }, 401);

  const url = Deno.env.get('SUPABASE_URL')!;
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const admin = createClient(url, serviceKey, { auth: { persistSession: false } });

  const { data: caller, error: callerErr } = await admin.auth.getUser(jwt);
  if (callerErr || !caller?.user) return json({ error: 'Jeton invalide.' }, 401);

  const { data: callerProfile, error: profErr } = await admin
    .from('profiles')
    .select('role')
    .eq('id', caller.user.id)
    .single();
  if (profErr || !callerProfile) return json({ error: 'Profil introuvable.' }, 403);
  if (callerProfile.role !== 'super_admin') {
    return json({ error: 'Réservé aux super admins.' }, 403);
  }

  let body: any;
  try {
    body = await req.json();
  } catch {
    return json({ error: 'Corps JSON invalide.' }, 400);
  }
  const action: string = body?.action ?? '';

  try {
    switch (action) {
      // -------------------------------------------------------------
      // list: auth.users merged with profiles (id → role / pole_id)
      // -------------------------------------------------------------
      case 'list': {
        const accounts: any[] = [];
        let page = 1;
        for (;;) {
          const { data, error } = await admin.auth.admin.listUsers({ page, perPage: 200 });
          if (error) throw toMsg(error);
          for (const u of data.users) {
            accounts.push(u);
            if (data.users.length < 200) break;
          }
          if (!data.users || data.users.length < 200 || page >= 20) break;
          page += 1;
        }

        const { data: profiles, error: pErr } = await admin
          .from('profiles')
          .select('id, role, pole_id, poles(code)')
          .neq('id', '00000000-0000-0000-0000-000000000000');
        if (pErr) throw toMsg(pErr);
        const byId = new Map((profiles ?? []).map((p: any) => [p.id, p]));

        const result = accounts.map((u: any) => {
          const prof: any = byId.get(u.id) ?? null;
          return {
            id: u.id,
            email: u.email ?? null,
            role: prof?.role ?? 'user',
            pole_id: prof?.pole_id ?? null,
            pole_code: prof?.poles?.code ?? null,
            email_confirmed: !!u.email_confirmed_at,
            last_sign_in_at: u.last_sign_in_at ?? null,
            created_at: u.created_at ?? null,
          };
        });
        return json(result);
      }

      // -------------------------------------------------------------
      // create: auth.user + profile role/pole (join in one call)
      // -------------------------------------------------------------
      case 'create': {
        const email = String(body.email ?? '').trim().toLowerCase();
        const password = String(body.password ?? '');
        const role = String(body.role ?? 'user');
        const poleId = body.pole_id ? String(body.pole_id) : null;

        if (!email || !email.includes('@')) return json({ error: 'Email invalide.' }, 400);
        if (password.length < 6) return json({ error: 'Mot de passe trop court (6 caractères minimum).' }, 400);
        if (!['user', 'pole_admin', 'super_admin'].includes(role)) {
          return json({ error: 'Rôle invalide.' }, 400);
        }
        if (poleId) {
          const { data: pole, error: pErr } = await admin
            .from('poles').select('id, archived_at').eq('id', poleId).maybeSingle();
          if (pErr) throw toMsg(pErr);
          if (!pole) return json({ error: 'Pôle introuvable.' }, 400);
          if (pole.archived_at) return json({ error: 'Pôle archivé — réactivez-le avant attribution.' }, 400);
        }

        const { data: created, error: cErr } = await admin.auth.admin.createUser({
          email,
          password,
          email_confirm: true, // created by an admin: no confirmation mail loop
        });
        if (cErr) throw toMsg(cErr);

        // handle_new_user fires on INSERT INTO auth.users, so a profile row
        // already exists with role 'user'; merge the requested role/pole in.
        const { error: uErr } = await admin.from('profiles').upsert({
          id: created.user!.id,
          role,
          pole_id: poleId,
        });
        if (uErr) throw toMsg(uErr);

        return json({ ok: true, id: created.user!.id });
      }

      // -------------------------------------------------------------
      // set_role (guarded: cannot leave zero super admins)
      // -------------------------------------------------------------
      case 'set_role': {
        const userId = String(body.user_id ?? '');
        const role = String(body.role ?? '');
        if (!userId) return json({ error: 'user_id manquant.' }, 400);
        if (!['user', 'pole_admin', 'super_admin'].includes(role)) {
          return json({ error: 'Rôle invalide.' }, 400);
        }

        const { data: target } = await admin.from('profiles').select('role').eq('id', userId).maybeSingle();
        if (!target) return json({ error: 'Profil introuvable.' }, 404);
        if (target.role === 'super_admin' && role !== 'super_admin') {
          const { count } = await admin
            .from('profiles').select('id', { count: 'exact', head: true }).eq('role', 'super_admin');
          if ((count ?? 0) <= 1) {
            return json({ error: 'Impossible : au moins un super admin doit rester.' }, 400);
          }
        }

        const { error } = await admin.from('profiles').update({ role }).eq('id', userId);
        if (error) throw toMsg(error);
        return json({ ok: true });
      }

      // -------------------------------------------------------------
      // assign_pole (null = "compte sans pôle" until assigned)
      // -------------------------------------------------------------
      case 'assign_pole': {
        const userId = String(body.user_id ?? '');
        const poleId = body.pole_id ? String(body.pole_id) : null;
        if (!userId) return json({ error: 'user_id manquant.' }, 400);

        if (poleId) {
          const { data: pole, error: pErr } = await admin
            .from('poles').select('id, archived_at').eq('id', poleId).maybeSingle();
          if (pErr) throw toMsg(pErr);
          if (!pole) return json({ error: 'Pôle introuvable.' }, 400);
          if (pole.archived_at) return json({ error: 'Pôle archivé — réactivez-le avant attribution.' }, 400);
        }

        const { error } = await admin.from('profiles').update({ pole_id: poleId }).eq('id', userId);
        if (error) throw toMsg(error);
        return json({ ok: true });
      }

      // -------------------------------------------------------------
      // delete_user (guarded: cannot delete the last super admin)
      // -------------------------------------------------------------
      case 'delete_user': {
        const userId = String(body.user_id ?? '');
        if (!userId) return json({ error: 'user_id manquant.' }, 400);
        if (userId === caller.user.id) return json({ error: 'Impossible de supprimer votre propre compte ici.' }, 400);

        const { data: target } = await admin.from('profiles').select('role').eq('id', userId).maybeSingle();
        if (target?.role === 'super_admin') {
          const { count } = await admin
            .from('profiles').select('id', { count: 'exact', head: true }).eq('role', 'super_admin');
          if ((count ?? 0) <= 1) {
            return json({ error: 'Impossible : au moins un super admin doit rester.' }, 400);
          }
        }

        const { error } = await admin.auth.admin.deleteUser(userId);
        if (error) throw toMsg(error);
        return json({ ok: true });
      }

      default:
        return json({ error: `Action inconnue : ${action}` }, 400);
    }
  } catch (e) {
    console.error('admin-users error', e);
    return json({ error: String(e?.message ?? e) }, 500);
  }
});

function toMsg(e: any): string {
  return e?.message ?? String(e);
}

